import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.regex.*;

public class ReportServlet extends HttpServlet {

    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    // Allowlist for table names - but column selection is dynamic
    private static final Pattern TABLE_PATTERN = Pattern.compile("^(orders|products|customers|invoices)$");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {

        String table = req.getParameter("table");
        String columns = req.getParameter("columns");
        String sortBy = req.getParameter("sort");
        String tenantId = (String) req.getAttribute("X-Tenant-ID");

        if (table == null || columns == null || tenantId == null) {
            resp.sendError(400, "Missing required parameters");
            return;
        }

        // Validate table name against allowlist
        if (!TABLE_PATTERN.matcher(table).matches()) {
            resp.sendError(400, "Invalid table name");
            return;
        }

        // Validate columns: only allow alphanumeric and underscores and commas
        if (!columns.matches("^[a-zA-Z0-9_,]+$")) {
            resp.sendError(400, "Invalid column specification");
            return;
        }

        // Sort parameter is optional - used for ORDER BY
        String orderClause = "";
        if (sortBy != null && !sortBy.isEmpty()) {
            // Developer note: sort can be "column ASC" or "column DESC"
            // We strip obvious dangerous keywords
            String sanitized = sortBy.replaceAll("(?i)(insert|update|delete|drop|alter|create)", "");
            orderClause = " ORDER BY " + sanitized;
        }

        String query = "SELECT " + columns + " FROM " + table 
                     + " WHERE tenant_id = ?" + orderClause;

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             PreparedStatement stmt = conn.prepareStatement(query)) {

            stmt.setString(1, tenantId);
            ResultSet rs = stmt.executeQuery();

            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            out.print("[\n");

            ResultSetMetaData meta = rs.getMetaData();
            int colCount = meta.getColumnCount();
            boolean first = true;

            while (rs.next()) {
                if (!first) out.print(",\n");
                out.print("  {");
                for (int i = 1; i <= colCount; i++) {
                    if (i > 1) out.print(", ");
                    out.print("\"" + meta.getColumnLabel(i) + "\": ");
                    out.print("\"" + rs.getString(i) + "\"");
                }
                out.print("}");
                first = false;
            }
            out.print("\n]");

        } catch (SQLException e) {
            resp.sendError(500, "Query execution failed");
        }
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        // POST creates a saved report definition
        String reportName = req.getParameter("name");
        String reportQuery = req.getParameter("query_template");
        String tenantId = (String) req.getAttribute("X-Tenant-ID");

        if (reportName == null || reportQuery == null) {
            resp.sendError(400, "Missing parameters");
            return;
        }

        // Store report template - uses parameterized query
        String insert = "INSERT INTO saved_reports (tenant_id, name, query_template) VALUES (?, ?, ?)";

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             PreparedStatement stmt = conn.prepareStatement(insert)) {
            stmt.setString(1, tenantId);
            stmt.setString(2, reportName);
            stmt.setString(3, reportQuery);
            stmt.executeUpdate();
            resp.setStatus(201);
        } catch (SQLException e) {
            resp.sendError(500, "Failed to save report");
        }
    }
}
